from math import pi
from qiskit import QuantumCircuit

qc = QuantumCircuit(5)

# Textbook QFT, with Qiskit's conventional qubit ordering and final reversal.
for target in range(4, -1, -1):
    qc.h(target)
    for control in range(target - 1, -1, -1):
        qc.cp(pi / (2 ** (target - control)), control, target)

for i in range(5 // 2):
    qc.swap(i, 4 - i)
